    localparam integer ROM_DEPTH = TIMBRE_N * DEPTH;
    reg signed [SAMPLE_W-1:0] rom_soft [0:ROM_DEPTH-1];
    reg signed [SAMPLE_W-1:0] rom_hard [0:ROM_DEPTH-1];
